use byond_dmb::{dmb::Dmb,bytecode};use std::{env,fs,path::PathBuf};fn main()->Result<(),Box<dyn std::error::Error>>{let a=env::args().collect::<Vec<_>>();let input=PathBuf::from(&a[1]);let output=PathBuf::from(&a[2]);let mut d=Dmb::from_bytes(&fs::read(&input)?)?;let id=d.procs.iter().position(|p|d.string(p.strings[0])==Some(b"/datum/unit_test/dq_constraint_parity/proc/mismatch")).ok_or("mismatch proc")?;let mut words=d.proc_code_words(id).ok_or("code")?.to_vec();let decoded=bytecode::decode(&words).map_err(|e|format!("{e:?}"))?;let mut count=0;for ins in decoded{if ins.opcode==0x50&&ins.operands==[30]{words[ins.offset+1]=1000;count+=1;}}if count!=1{return Err(format!("expected1 literal got{count}").into());}d.replace_proc_code(id,&bytecode::decode(&words).map_err(|e|format!("{e:?}"))?)?;d.validate_references()?;let bytes=d.to_bytes()?;Dmb::from_bytes(&bytes)?.validate_references()?;fs::create_dir_all(output.parent().ok_or("parent")?)?;fs::write(&output,bytes)?;fs::copy(input.with_extension("rsc"),output.with_extension("rsc"))?;println!("reportlimit {id} 30->1000");Ok(())}
